SELECT


WHERE p.deleted = 0

    AND (p.title LIKE CONCAT('%', #{query.keyword}, '%')
    OR p.description LIKE CONCAT('%', #{query.keyword}, '%'))


    AND p.category_id = #{query.categoryId}


    AND p.seller_id = #{query.sellerId}


    AND p.status = #{query.status}


    AND p.price >= #{query.minPrice}


    AND p.price <= #{query.maxPrice}


ORDER BY

    p.price ASC, p.id DESC
    p.price DESC, p.id DESC
    p.view_count DESC, p.id DESC
    p.create_time DESC, p.id DESC

SELECT


WHERE p.deleted = 0 AND p.id IN

    #{id}
